using System;using System.IO;using System.Linq;using System.Drawing;using System.Windows.Forms;using System.Reflection;using System.Threading;
namespace Frociart.Tests {internal static class SnapshotTests {
static int checks;static readonly string Folder=Path.Combine(Path.GetDirectoryName(Assembly.GetExecutingAssembly().Location),"screenshots");
static void Check(bool b,string why){checks++;if(!b)throw new Exception(why);Console.WriteLine("PASS "+why);}
static object Call(object o,string n,params object[] args){return o.GetType().GetMethod(n,BindingFlags.NonPublic|BindingFlags.Public|BindingFlags.Instance).Invoke(o,args);}
static T Field<T>(object o,string n){return(T)o.GetType().GetField(n,BindingFlags.NonPublic|BindingFlags.Public|BindingFlags.Instance).GetValue(o);}
static void Pump(){var end=DateTime.UtcNow.AddMilliseconds(300);do{Application.DoEvents();Thread.Sleep(4);}while(DateTime.UtcNow<end);}
[STAThread]static int Main(){try{Application.EnableVisualStyles();Directory.CreateDirectory(Folder);Environment.SetEnvironmentVariable("FROCIART_DATA_DIR",Path.Combine(Folder,"isolated"));
var d=FlowPseudocode.Decode("prezzi = [12.5, 8, 24]\ntotale = somma(prezzi)\nSTAMPA \"Totale: \" + totale");d.Title="Spese della settimana";FlowLayout.Arrange(d);var r=new Interpreter(d);for(int i=0;i<20&&r.State!=RuntimeState.Completed;i++)r.Step();Check(r.State==RuntimeState.Completed,"Fixture completed");
var report=new ExecutionSnapshot(d,r);Check(report.Rows.Count(x=>x.Name.StartsWith("["))==3,"All vector indices captured");Check(report.Rows.Any(x=>x.Name=="totale"&&x.Value=="44.5"),"Scalar value exact");Check(report.Rows.Any(x=>x.Value=="Totale: 44.5"),"Output exact");r.Reset();Check(report.Rows.Any(x=>x.Value=="44.5"),"Snapshot survives runner reset");
using(var canvas=new FlowCanvas{Diagram=d}){string before=FlowPseudocode.Encode(d);float zoom=canvas.Zoom;using(var image=report.Render(canvas)){Check(image.Width>=1280&&image.Height>600,"Readable image dimensions");string path=Path.Combine(Folder,"diagramma-e-dati.png");ExecutionSnapshot.Save(image,path);using(var actual=new Bitmap(path))Check(actual.Size==image.Size,"PNG saved at full resolution");ExecutionSnapshot.Save(image,path);Check(Directory.GetFiles(Folder,"*.tmp").Length==0,"Atomic overwrite leaves no temporary files");using(var dialog=new SnapshotDialog(image,d.Title)){dialog.ShowInTaskbar=false;dialog.Location=new Point(-3000,-3000);dialog.Show();Pump();Check(dialog.Controls.Count==2,"Preview has controls and scrollable image");dialog.Close();}}Check(before==FlowPseudocode.Encode(d)&&zoom==canvas.Zoom,"Report preserves graph and zoom");
 var longReport=new ExecutionSnapshot(d,null);longReport.Rows.Add(new ExecutionSnapshot.Row{Name="nome_variabile_lungo_da_leggere",Value=new String('W',240)+" caffè 🙂\nseconda riga"});using(var image=longReport.Render(canvas))ExecutionSnapshot.Save(image,Path.Combine(Folder,"long-values.png"));Check(longReport.Rows.Last().Value.EndsWith("seconda riga"),"Long and multiline values retained");
 var tooLong=new ExecutionSnapshot(d,null);for(int i=0;i<1000;i++)tooLong.Rows.Add(new ExecutionSnapshot.Row{Name="["+i+"]",Value="dato"});bool rejected=false;try{using(var ignored=tooLong.Render(canvas)){} }catch(InvalidOperationException){rejected=true;}Check(rejected,"Oversized report refuses unreadable shrink or truncation");}
using(var f=new MainForm(null,true)){f.ShowInTaskbar=false;f.Location=new Point(-3000,-3000);f.Size=new Size(1360,850);f.Show();Pump();f.SetDocument(d,null,false);f.EnterEditor();f.SingleStep();while(f.Runner.State!=RuntimeState.Completed)f.SingleStep();Pump();var variables=Field<ListView>(f,"variables");Console.WriteLine("VARIABLES visible="+variables.Visible+" font="+variables.Font.Size+" items="+variables.Items.Count);for(Control c=variables;c!=null;c=c.Parent)Console.WriteLine(c.GetType().Name+" "+c.Visible+" "+c.Size);using(var diag=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(diag,new Rectangle(Point.Empty,f.Size));diag.Save(Path.Combine(Folder,"runtime-diagnostic.png"));}Check(variables.Visible&&variables.Font.Size>=12,"Variables visible by default with larger text");Check(variables.Items.Count==2,"Native list contains scalar and vector");Check(Field<FlowButton>(f,"runtimeSnapshotButton").Visible,"Capture action visible during execution");using(var bitmap=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(bitmap,new Rectangle(Point.Empty,f.Size));bitmap.Save(Path.Combine(Folder,"runtime-pc.png"));}f.SetDocument(new Diagram(),null,false);f.Close();}
Console.WriteLine("SNAPSHOT PASS "+checks);return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}
}}
